                    continue;
                }
                JointTransform mirroredTransform = mirrorJointTransform(e.getValue().transform, JointTransform.empty());
                mirrored.put(e.getKey(), new JointTransform.TransformEntry(e.getValue().multiplyFunction, mirroredTransform));
            }

            entries.clear();
