        tooltip.add(Component.translatable("item.cataclysm.ceraunus.desc").withStyle(ChatFormatting.DARK_GREEN));
        tooltip.add(Component.translatable("item.cataclysm.ceraunus2.desc").withStyle(ChatFormatting.DARK_GREEN));
    }
}

