        this.setDeltaMovement(vec3.multiply((double) 0.99F, (double) 0.98F, (double) 0.99F));
    }


    protected void attackEntities(double strength,double x,double z) {
        AABB bashBox = this.getBoundingBox().inflate(0.01f);
        DamageSource source = damageSources().mobProjectile(this, owner);
        for (LivingEntity entity : this.level().getEntitiesOfClass(LivingEntity.class, bashBox)) {
            if ((owner == null || !owner.equals(entity) && !owner.isAlliedTo(entity) && !entity.isAlliedTo(owner))) {
                boolean flag = entity.hurt(source, this.getDamage());

                if(flag) {
                    entity.extinguishFire();
                    MobEffectInstance effectinstance1 = entity.getEffect(ModEffect.EFFECTWETNESS.get());
                    int i = 1;
                    if (effectinstance1 != null) {
                        i += effectinstance1.getAmplifier();
                        entity.removeEffectNoUpdate(ModEffect.EFFECTWETNESS.get());
                    } else {
                        --i;
                    }

                    i = Mth.clamp(i, 0, 4);
                    MobEffectInstance effectinstance = new MobEffectInstance(ModEffect.EFFECTWETNESS.get(), 200, i, false, true, true);
                    entity.addEffect(effectinstance);
                }

                entity.hasImpulse = true;
                Vec3 vec3;
                for(vec3 = entity.getDeltaMovement(); x * x + z * z < (double)1.0E-5F; z = (Math.random() - Math.random()) * 0.01) {
                    x = (Math.random() - Math.random()) * 0.01;
                }
                double playerSize = 0.6 * 1.8;
                double entitySize = entity.getBbWidth() * entity.getBbHeight();
                double scale = playerSize / Math.max(0.1, entitySize); // 최소값 보정
                double knockbackScale = Math.min(scale, 1.5);
                double adjustedStrength = strength * knockbackScale;

                Vec3 knockback = new Vec3(x, 0, z).normalize().scale(adjustedStrength);

                entity.setDeltaMovement(vec3.x / (double)2.0F - knockback.x, entity.onGround() ? Math.min(0.5, vec3.y / (double)2.0F + strength) : vec3.y, vec3.z / (double)2.0F - knockback.z);
