        float f = Math.max(1F - (this.getLifespan() / (1F * getMaxTicks())), 0F);
        Vec3 directionVec = new Vec3(0, 0, f * f * 0.1F).yRot((float) Math.toRadians(-this.getYRot()));
        if (this.level().isClientSide) {
            if (this.lSteps > 0) {
                double d5 = this.getX() + (this.lx - this.getX()) / (double) this.lSteps;
                double d6 = this.getY() + (this.ly - this.getY()) / (double) this.lSteps;
                double d7 = this.getZ() + (this.lz - this.getZ()) / (double) this.lSteps;
                this.setYRot(Mth.wrapDegrees((float) this.lyr));
                this.setXRot(this.getXRot() + (float) (this.lxr - (double) this.getXRot()) / (float) this.lSteps);
                --this.lSteps;
                this.setPos(d5, d6, d7);
            } else {
                this.reapplyPosition();
            }
            if (!this.clientSideAttackEnded) {
                for (int particleCount = 0; particleCount < 2; particleCount++) {
                    for (int i = 0; i < 2; i++) {
                        float xOffset = (float) (i - 1) / 2.0F + 0.25F + (random.nextFloat() - 0.5F) * 0.2F;
                        int rand = this.random.nextInt(20);
                        spawnParticleAt((0.1F + random.nextFloat() * 0.2F), 0.7F, xOffset * 3.5F, new CustomPoofParticleOptions(76 + rand, 147 + rand, 173 + rand, 0.1F));
                    }
                }
            }
        } else {
            this.reapplyPosition();
            this.setRot(this.getYRot(), this.getXRot());
            attackEntities(1.5,Mth.sin(this.getYRot() * ((float) Math.PI / 180F)), (-Mth.cos(this.getYRot() * ((float) Math.PI / 180F))));
        }



        Vec3 vec3 = this.getDeltaMovement().scale(0.9F).add(directionVec);
        this.move(MoverType.SELF, vec3);
        this.setDeltaMovement(vec3.multiply((double) 0.99F, (double) 0.98F, (double) 0.99F));
    }


    protected void attackEntities(double strength,double x,double z) {
        AABB bashBox = this.getBoundingBox().inflate(0.01f);
        DamageSource source = damageSources().mobProjectile(this, owner);
        for (LivingEntity entity : this.level().getEntitiesOfClass(LivingEntity.class, bashBox)) {
            if ((owner == null || !owner.equals(entity) && !owner.isAlliedTo(entity) && !entity.isAlliedTo(owner))) {
                boolean flag = entity.hurt(source, this.getDamage());

                if(flag) {
                    entity.extinguishFire();
                    MobEffectInstance effectinstance1 = entity.getEffect(ModEffect.EFFECTWETNESS.get());
                    int i = 1;
                    if (effectinstance1 != null) {
                        i += effectinstance1.getAmplifier();
                        entity.removeEffectNoUpdate(ModEffect.EFFECTWETNESS.get());
                    } else {
                        --i;
                    }

                    i = Mth.clamp(i, 0, 4);
                    MobEffectInstance effectinstance = new MobEffectInstance(ModEffect.EFFECTWETNESS.get(), 200, i, false, true, true);
                    entity.addEffect(effectinstance);
                }

                entity.hasImpulse = true;
                Vec3 vec3;
                for(vec3 = entity.getDeltaMovement(); x * x + z * z < (double)1.0E-5F; z = (Math.random() - Math.random()) * 0.01) {
                    x = (Math.random() - Math.random()) * 0.01;
                }
                double playerSize = 0.6 * 1.8;
                double entitySize = entity.getBbWidth() * entity.getBbHeight();
                double scale = playerSize / Math.max(0.1, entitySize); // 최소값 보정
                double knockbackScale = Math.min(scale, 1.5);
                double adjustedStrength = strength * knockbackScale;

                Vec3 knockback = new Vec3(x, 0, z).normalize().scale(adjustedStrength);

                entity.setDeltaMovement(vec3.x / (double)2.0F - knockback.x, entity.onGround() ? Math.min(0.5, vec3.y / (double)2.0F + strength) : vec3.y, vec3.z / (double)2.0F - knockback.z);
            }
        }
    }

    @OnlyIn(Dist.CLIENT)
    public void handleEntityEvent(byte id) {
        super.handleEntityEvent(id);
        if (id == 4) {
            this.clientSideAttackEnded = true;

        }

    }



    @Override
    public void lerpTo(double x, double y, double z, float yr, float xr, int steps,boolean bool) {
        this.lx = x;
        this.ly = y;
        this.lz = z;
        this.lyr = yr;
        this.lxr = xr;
        this.lSteps = steps;
        this.setDeltaMovement(this.lxd, this.lyd, this.lzd);
    }

    @Override
    public void lerpMotion(double lerpX, double lerpY, double lerpZ) {
        this.lxd = lerpX;
        this.lyd = lerpY;
        this.lzd = lerpZ;
        this.setDeltaMovement(this.lxd, this.lyd, this.lzd);
    }
}

